	private static Map<Map<String, String>, Long> evaluate(SailRepository repository, String queryText) {
		Map<Map<String, String>, Long> bag = new LinkedHashMap<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			try (var rows = connection.prepareTupleQuery(QueryLanguage.SPARQL, queryText).evaluate()) {
				while (rows.hasNext()) {
					BindingSet row = rows.next();
					Map<String, String> canonical = new LinkedHashMap<>();
					for (String name : new TreeSet<>(row.getBindingNames())) {
						Value value = row.getValue(name);
						assertThat(value).as("bound result names have non-null values: %s", name).isNotNull();
						canonical.put(name, NTriplesUtil.toNTriplesString(value));
					}
					bag.merge(Map.copyOf(canonical), 1L, Long::sum);
				}
			}
		}
		return Map.copyOf(bag);
	}

