	private static void assertFixtureExercisesOptionalAndRepeatedFrames(Map<Map<String, String>, Long> bag) {
		String patient1 = "<urn:q11:patient:1>";
		assertThat(bag.keySet().stream().filter(row -> patient1.equals(row.get("root"))).count())
				.as("the same patient is naturally revisited with different encounter/observation frames")
				.isGreaterThan(1L);
		assertThat(bag.keySet().stream().map(row -> row.get("root") + "|" + row.get("encounter") + "|"
				+ row.get("observation")).distinct().count())
				.as("the public q11 bindings contain distinct correlated base frames")
				.isGreaterThan(1L);
		assertThat(bag.keySet().stream().anyMatch(row -> row.containsKey("observationValue")))
				.as("the fixture has a present observation value").isTrue();
		assertThat(bag.keySet().stream().anyMatch(row -> !row.containsKey("observationValue")))
				.as("the fixture has an optional observation value absence").isTrue();
		assertThat(bag.keySet().stream().anyMatch(row -> !row.containsKey("recordedOn")))
				.as("the fixture has an optional encounter-date absence").isTrue();
		Set<String> matchingMedicationIds = new TreeSet<>();
		bag.keySet().stream()
				.filter(row -> "\"MED-1001\"".equals(row.get("medicationCode")))
				.map(row -> row.get("medication"))
				.forEach(matchingMedicationIds::add);
		assertThat(matchingMedicationIds)
				.as("distinct medication resources share the same optional code/dosage values")
				.hasSizeGreaterThan(1);
		assertThat(bag.values()).allSatisfy(count -> assertThat(count).isEqualTo(1L));
	}

	private static long collectNativeNodes(GenericPlanNode node, List<String> actualNodes) {
		String path = node.getStringMetricActual("nativeExecutionPath");
		Long invocations = node.getLongMetricActual("nativeInvocationsActual");
		if (path != null || invocations != null) {
			actualNodes.add(node.getType() + "{path=" + path + ", invocations=" + invocations + "}");
		}
		long total = invocations == null ? 0L : invocations;
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				total += collectNativeNodes(child, actualNodes);
			}
		}
		return total;
	}
